//! Procedural macros that generate Rust source code as `TokenStream`s.
//!
//! This crate is intentionally small: it parses input with [`syn`] and builds
//! new Rust items by composing token streams with [`quote!`]. The result is a
//! normal `TokenStream` that the compiler then treats as source code.

use proc_macro::TokenStream;
use quote::{format_ident, quote};
use syn::parse_macro_input;
use syn::{Field, Fields, Ident, ItemStruct};

/// Generates a struct and a `new` constructor from a compact declaration.
///
/// Input syntax:
///
/// ```ignore
/// make_struct! {
///     Point {
///         x: f64,
///         y: f64,
///     }
/// }
/// ```
///
/// expands to the struct plus:
///
/// ```ignore
/// impl Point {
///     pub fn new(x: f64, y: f64) -> Self {
///         Self { x, y }
///     }
/// }
/// ```
#[proc_macro]
pub fn make_struct(input: TokenStream) -> TokenStream {
    let input = parse_macro_input!(input as ItemStruct);
    expand_struct(input)
        .unwrap_or_else(syn::Error::into_compile_error)
        .into()
}
```

