fn expand_struct(item: ItemStruct) -> syn::Result<TokenStream2> {
    let name = &item.ident;
    let (impl_generics, ty_generics, where_clause) = item.generics.split_for_impl();

    let (params, fields) = match &item.fields {
        Fields::Named(named) => {
            let idents: Vec<&Ident> = named.named.iter().map(|f| f.ident.as_ref().unwrap()).collect();
            let types: Vec<&syn::Type> = named.named.iter().map(|f| &f.ty).collect();
            let params = idents.iter().zip(types.iter()).map(|(id, ty)| quote!(#id: #ty));
            let fields = idents.iter().map(|id| quote!(#id));
            (quote!(#(#params),*), quote!(#(#fields),*))
        }
        Fields::Unnamed(unnamed) => {
            let types: Vec<&syn::Type> = unnamed.unnamed.iter().map(|f| &f.ty).collect();
            let params = types.iter().enumerate().map(|(i, ty)| {
                let id = format_ident!("field{}", i);
                quote!(#id: #ty)
